package com.coxmegascale;

import java.util.EnumSet;
import java.util.Set;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Persistent RuneLite settings for global visibility, local fixture logging,
 * welcome-page behavior, and the defaults used to seed a new sidebar session.
 */
@ConfigGroup(CoxMegascaleConfig.GROUP)
public interface CoxMegascaleConfig extends Config
{
	String GROUP = "coxmegascale";

	@ConfigSection(
		name = "Scout notifications",
		description = "Choose which perfect scout layout families produce a RuneLite notification.",
		position = 0
	)
	String scoutNotifications = "scoutNotifications";

	@ConfigItem(
		keyName = "notifiedScoutLayouts",
		name = "Notify for layouts",
		description = "Select one or more layout families. FS includes FSCC; select only FSCC for an exact FSCC preference.",
		position = 0,
		section = scoutNotifications
	)
	default Set<ScoutLayout> notifiedScoutLayouts()
	{
		return EnumSet.of(ScoutLayout.FSCC);
	}

	@ConfigItem(
		keyName = "showInfoBoxes",
		name = "Show infoboxes",
		description = "Show CoX Assistant infoboxes while inside a scouted raid."
	)
	default boolean showInfoBoxes()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pointFixtureLogging",
		name = "Log point fixtures",
		description = "Opt-in anonymous local JSONL logging. Review and manually share only point-fixtures files in Discord #point-data."
	)
	default boolean pointFixtureLogging()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showWelcomeOnStartup",
		name = "Show welcome on startup",
		description = "Open the CoX Assistant welcome, usage, and estimate notice whenever the plugin starts."
	)
	default boolean showWelcomeOnStartup()
	{
		return true;
	}

    @Range(min = 1, max = 100)
    @ConfigItem(
        keyName = "defaultScale",
        name = "Default scale",
        description = "Default raid scale used when the panel opens."
    )
    default int defaultScale()
    {
        return 100;
    }

    @Range(min = 0, max = 5000)
    @ConfigItem(
        keyName = "defaultThievingLevel",
        name = "Default total thieving",
        description = "Default total thieving level for thieving room point estimates."
    )
    default int defaultThievingLevel()
    {
        return 0;
    }

    @Range(min = 60, max = 99)
    @ConfigItem(
        keyName = "defaultFishingLevel",
        name = "Default fishing level",
        description = "Default fishing level for fishing room point estimates."
    )
    default int defaultFishingLevel()
    {
        return 75;
    }
}

package com.coxmegascale;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.function.BooleanSupplier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxPriority;

/**
 * Conditional infobox for one weapon in the active Mystics defence plan. The
 * supplied visibility gate keeps global, raid, and scout requirements in the
 * plugin coordinator instead of duplicating them here.
 */
public class CoxMegascaleMysticsSpecInfoBox extends InfoBox
{
    private final CoxMegascaleState state;
    private final String weapon;
    private final BooleanSupplier isVisible;

    CoxMegascaleMysticsSpecInfoBox(BufferedImage image, Plugin plugin, CoxMegascaleState state, String weapon, BooleanSupplier isVisible)
    {
        super(image, plugin);
        this.state = state;
        this.weapon = weapon;
        this.isVisible = isVisible;
        setPriority(InfoBoxPriority.HIGH);
        setTooltip("Mystics " + weapon + " remaining");
    }

    @Override
    public String getText()
    {
        return Integer.toString(state.getMysticsSpecRemaining(weapon));
    }

    @Override
    public Color getTextColor()
    {
        return state.getMysticsSpecRemaining(weapon) == 0 ? Color.GREEN : Color.WHITE;
    }

    @Override
    public boolean render()
    {
        return isVisible.getAsBoolean() && state.isMysticsTrackerActive() && state.isMysticsSpecTracked(weapon);
    }

    @Override
    public String getName()
    {
        return super.getName() + "_mystics_" + weapon;
    }
}

