                roomName = "Mystics";
                break;
            case "shamans":
                roomName = "Shamans";
                break;
            case "muttadiles":
                roomName = "Muttadiles";
                break;
            case "tekton":
                roomName = "Tekton";
                break;
            case "vasa":
                roomName = "Vasa";
                break;
            case "vespula":
                roomName = "Vespula";
                break;
            case "vanguards":
                roomName = "Vanguards";
                break;
            case "tightrope":
                roomName = "Tightrope";
                break;
            case "thieving":
                roomName = "Thieving";
                break;
            case "iceDemon":
                roomName = "Ice Demon";
                break;
            case "crabs":
                roomName = "Crabs";
                break;
            default:
                return true;
