    private boolean observeSharedStorageCounts(int[] counts)
    {
        boolean changed = false;
        for (int i = 0; i < RESOURCES.size(); i++)
        {
            Resource resource = RESOURCES.get(i);
            changed |= putCount(sharedStorageCounts, resource.key, counts[i]);
        }
        for (int i = 0; i < COX_POTIONS.size(); i++)
        {
            Potion potion = COX_POTIONS.get(i);
            changed |= putCount(sharedStorageCounts, potion.key, counts[RESOURCES.size() + i]);
        }
        if (changed || sharedStorageObservedAtMillis == 0)
        {
            sharedStorageObservedAtMillis = Math.max(System.currentTimeMillis(), sharedStorageObservedAtMillis + 1);
            changed = true;
        }
        return changed;
    }

    private static int[] trackedCounts(ItemContainer container)
    {
        int[] counts = new int[RESOURCES.size() + COX_POTIONS.size()];
        Item[] items = container.getItems();
        if (items == null)
        {
            return counts;
        }
        for (Item item : items)
        {
            if (item == null || item.getQuantity() <= 0)
            {
                continue;
            }
            Integer trackedIndex = TRACKED_INVENTORY_INDEX.get(item.getId());
            if (trackedIndex != null)
            {
                counts[trackedIndex] += item.getQuantity();
            }
        }
        return counts;
    }

    private boolean updateResourceCounts(Map<String, Integer> destination, int[] counts)
    {
        boolean changed = false;
        for (int i = 0; i < RESOURCES.size(); i++)
        {
            changed |= putCount(destination, RESOURCES.get(i).key, counts[i]);
        }
        return changed;
    }

    private boolean updateCollectedCounts()
    {
        boolean changed = false;
        for (Resource resource : RESOURCES)
        {
            int total = inventoryResourceCounts.getOrDefault(resource.key, 0)
                + privateStorageResourceCounts.getOrDefault(resource.key, 0);
            changed |= putCount(collectedCounts, resource.key, total);
        }
        return changed;
    }

    private static boolean putCount(Map<String, Integer> counts, String key, int value)
    {
        int safeValue = Math.max(0, value);
        if (counts.getOrDefault(key, 0) == safeValue)
        {
            return false;
        }
        counts.put(key, safeValue);
        return true;
    }

    private static int saturatedInt(long value)
    {
        return (int) Math.max(0, Math.min(Integer.MAX_VALUE, value));
    }

    private void markPrepChanged()
    {
        prepRevision++;
    }

    private static Map<Integer, Integer> buildTrackedInventoryIndex()
    {
        Map<Integer, Integer> index = new LinkedHashMap<>();
        for (int i = 0; i < RESOURCES.size(); i++)
        {
            Resource resource = RESOURCES.get(i);
            index.put(resource.cleanItemId, i);
            index.put(resource.grimyItemId, i);
        }
        for (int i = 0; i < COX_POTIONS.size(); i++)
        {
            for (int itemId : COX_POTIONS.get(i).itemIds)
            {
                index.put(itemId, RESOURCES.size() + i);
            }
        }
        return Collections.unmodifiableMap(index);
    }

    public static class Resource
    {
        public final String key;
        public final int cleanItemId;
        public final int grimyItemId;

        Resource(String key, int cleanItemId, int grimyItemId)
        {
            this.key = key;
            this.cleanItemId = cleanItemId;
            this.grimyItemId = grimyItemId;
        }
    }

    public static class ScoutedRoom
    {
        public final String type;
        public final String name;

        public ScoutedRoom(String type, String name)
        {
            this.type = type;
            this.name = name;
        }
    }

    public static class TrackedRoomPoints
    {
        public final String room;
        public final int personalPoints;
        public final int groupPoints;
        public final long durationMillis;

        TrackedRoomPoints(String room, int personalPoints, int groupPoints)
        {
            this(room, personalPoints, groupPoints, 0);
        }

        TrackedRoomPoints(String room, int personalPoints, int groupPoints, long durationMillis)
        {
            this.room = room;
            this.personalPoints = personalPoints;
            this.groupPoints = groupPoints;
            this.durationMillis = Math.max(0, durationMillis);
        }
    }

    public static class DeathPointLoss
    {
        public final String room;
        public final int pointsLost;

        DeathPointLoss(String room, int pointsLost)
        {
            this.room = room;
            this.pointsLost = pointsLost;
        }
    }

    private static class FishType
    {
        final int itemId;
        final String name;
        final int points;

        FishType(int itemId, String name, int points)
        {
            this.itemId = itemId;
            this.name = name;
            this.points = points;
        }
    }

    private static class Potion
    {
        final String key;
        final int[] itemIds;

        Potion(String key, int... itemIds)
        {
            this.key = key;
            this.itemIds = itemIds;
        }

        int doseForItem(int itemId)
        {
            for (int i = 0; i < itemIds.length; i++)
            {
                if (itemIds[i] == itemId)
                {
                    return i % 4 + 1;
                }
            }
            return 0;
        }

    }

    public static class TeamMember
    {
        public final long memberId;
        public String displayName = "Unknown";
        public boolean hasCoxData;
        public int personalPoints;
        public String activeRoom;
        public int overloadSips;
        public int nonOverloadSips;
        public int thievingLevel;
        public boolean hasThievingLevel;
        public final List<CoxTeamUpdate.Fish> fishEaten = new ArrayList<>();
        public final List<TeamDeath> deaths = new ArrayList<>();
        public final Map<String, Integer> prepResources = new LinkedHashMap<>();
        public final Map<String, Integer> craftedPotions = new LinkedHashMap<>();

        TeamMember(long memberId)
        {
            this.memberId = memberId;
        }

        public int getDeathPointsLost()
        {
            long total = 0;
            for (TeamDeath death : deaths)
            {
                total += death.pointsLost;
            }
            return saturatedInt(total);
        }

        public int getFishCount()
        {
            long total = 0;
            for (CoxTeamUpdate.Fish fish : fishEaten)
            {
                total += Math.max(0, fish.count);
            }
            return saturatedInt(total);
        }

        public int getFishPoints()
        {
            long total = 0;
            for (CoxTeamUpdate.Fish fish : fishEaten)
            {
                total += Math.max(0, fish.points) * Math.max(0, fish.count);
            }
            return saturatedInt(total);
        }

        public int getPrepResourceCount(String resource)
        {
            return prepResources.getOrDefault(resource, 0);
        }

        public int getCraftedPotionCount(String potion)
        {
            return craftedPotions.getOrDefault(potion, 0);
        }
    }

    public static class TeamDeath
    {
        public final String room;
        public final int pointsLost;
        public final long occurredAtMillis;

        TeamDeath(String room, int pointsLost, long occurredAtMillis)
        {
            this.room = room == null || room.isEmpty() ? "Unknown" : room;
            this.pointsLost = Math.max(0, pointsLost);
            this.occurredAtMillis = occurredAtMillis;
        }
    }

    private static class PendingLocalDeath
    {
        final String room;
        final long occurredAtMillis;

        PendingLocalDeath(String room, long occurredAtMillis)
        {
            this.room = room;
            this.occurredAtMillis = occurredAtMillis;
        }
    }

    private static class RecentGroupLoss
    {
        final String room;
        final int pointsLost;
        final long occurredAtMillis;
        boolean assigned;

        RecentGroupLoss(String room, int pointsLost, long occurredAtMillis)
        {
            this.room = room;
            this.pointsLost = pointsLost;
            this.occurredAtMillis = occurredAtMillis;
        }
    }
}

package com.coxmegascale;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Comparator;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

/**
 * Opt-in, local-only anonymous JSONL recorder for calibrating raid points.
 * Records contain bounded raid metadata and relative timing, never display
 * names, account/session data, chat, coordinates, or wall-clock timestamps.
 * Disk writes run on one daemon thread so I/O cannot block the client thread.
 */
final class PointFixtureLogger implements AutoCloseable
{
    static final int SCHEMA_VERSION = 2;

    private final boolean enabled;
    private final Path directory;
    private final ExecutorService writer = Executors.newSingleThreadExecutor(r ->
    {
        Thread thread = new Thread(r, "cox-point-fixture-writer");
        thread.setDaemon(true);
        return thread;
    });

    private BufferedWriter output;
    private String sessionId;
    private Path sessionDirectory;
    private String sessionFileName;
    private Metadata metadata;
    private long sessionStartedNanos;
    private int sequence;
    private int lastGroupPoints;
    private int lastPersonalPoints;
    private String pendingStartLine;

    PointFixtureLogger(boolean enabled, Path configDirectory)
    {
        this.enabled = enabled;
        this.directory = configDirectory.resolve("cox-assistant").resolve("point-fixtures");
    }

    void startRaid(Metadata metadata, int groupPoints, int personalPoints)
    {
        // A random session id separates files without encoding player identity.
        synchronized (this)
        {
            if (!enabled || sessionId != null)
            {
                return;
            }
            this.metadata = metadata;
            sessionId = UUID.randomUUID().toString();
            lastGroupPoints = groupPoints;
            lastPersonalPoints = personalPoints;
            sequence = 0;
            pendingStartLine = null;
            sessionStartedNanos = System.nanoTime();
            String modeDirectory = modeDirectory(metadata.raidMode);
            sessionDirectory = directory.resolve(modeDirectory);
            sessionFileName = modeDirectory + "-" + sessionId + ".jsonl";
        }
        record("raid_start", null, groupPoints, personalPoints, "raid_start", null, null, true);
    }

    synchronized boolean hasActiveSession()
    {
        return enabled && sessionId != null;
    }

    void room(String event, String room, int groupPoints, int personalPoints, String pointSource)
    {
        record(event, room, groupPoints, personalPoints, pointSource, null, null, false);
    }

    void raidComplete(int groupPoints, int personalPoints)
    {
        record("raid_complete", null, groupPoints, personalPoints, "raid_complete", true, "completed", false);
        finishSessionWithoutRecord();
    }

    void endSession(String reason)
    {
        if (!hasActiveSession())
        {
            return;
        }
        record("raid_end", null, currentGroupPoints(), currentPersonalPoints(), "session_boundary", false, reason, false);
        finishSessionWithoutRecord();
    }

    private synchronized int currentGroupPoints()
    {
        return lastGroupPoints;
    }

    private synchronized int currentPersonalPoints()
    {
        return lastPersonalPoints;
    }

    private void finishSessionWithoutRecord()
    {
        if (!enabled)
        {
            return;
        }

        synchronized (this)
        {
            if (sessionId == null)
            {
                return;
            }
            sessionId = null;
            sessionDirectory = null;
            sessionFileName = null;
            metadata = null;
            pendingStartLine = null;
        }
        // Queue closure behind all pending records to preserve JSONL ordering.
        writer.execute(this::closeOutput);
    }

    private synchronized void record(
        String event,
        String room,
        int groupPoints,
        int personalPoints,
        String pointSource,
        Boolean completed,
        String endReason,
        boolean includeMetadata
    )
    {
        if (!enabled || sessionId == null || metadata == null)
        {
            return;
        }

        // Absolute totals make fixtures independently auditable while deltas are
        // the values used to calibrate room boundaries and point sources.
        int groupDelta = groupPoints - lastGroupPoints;
        int personalDelta = personalPoints - lastPersonalPoints;
        lastGroupPoints = groupPoints;
        lastPersonalPoints = personalPoints;
        long elapsedMillis = Math.max(0L, TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - sessionStartedNanos));
        StringBuilder line = new StringBuilder(320)
            .append("{\"schemaVersion\":").append(SCHEMA_VERSION)
            .append(",\"event\":").append(quote(event))
            .append(",\"sequence\":").append(sequence++)
            .append(",\"elapsedMs\":").append(elapsedMillis)
            .append(",\"roomContext\":").append(quote(bounded(room, 40)))
            .append(",\"pointSource\":").append(quote(bounded(pointSource, 40)))
            .append(",\"groupPoints\":").append(groupPoints)
            .append(",\"groupDelta\":").append(groupDelta)
            .append(",\"personalPoints\":").append(personalPoints)
            .append(",\"personalDelta\":").append(personalDelta);

        if (includeMetadata)
        {
            line.append(",\"raidMode\":").append(quote(metadata.raidMode))
                .append(",\"startReason\":").append(quote(metadata.startReason))
                .append(",\"layoutCode\":").append(quote(metadata.layoutCode))
                .append(",\"scale\":").append(metadata.scale)
                .append(",\"scaleSource\":").append(quote(metadata.scaleSource))
                .append(",\"thievingLevel\":").append(metadata.thievingLevel)
                .append(",\"thievingSource\":").append(quote(metadata.thievingSource))
                .append(",\"fishingLevel\":").append(metadata.fishingLevel)
                .append(",\"fishingSource\":").append(quote(metadata.fishingSource));
        }
        if (completed != null)
        {
            line.append(",\"completed\":").append(completed);
        }
        if (endReason != null)
        {
            line.append(",\"endReason\":").append(quote(bounded(endReason, 32)));
        }
        line.append("}\n");

        Path writeDirectory = sessionDirectory;
        String writeFileName = sessionFileName;
        if ("raid_start".equals(event))
        {
            pendingStartLine = line.toString();
            return;
        }
        if ("raid_end".equals(event) && pendingStartLine != null)
        {
            // Do not create an empty/start-only file when tracking ends before
            // the first room, point change, or completion record.
            pendingStartLine = null;
            return;
        }
        String writeLine = (pendingStartLine == null ? "" : pendingStartLine) + line;
        pendingStartLine = null;
        writer.execute(() -> write(writeLine, writeDirectory, writeFileName));
    }

    private synchronized void write(String line, Path writeDirectory, String writeFileName)
    {
        try
        {
            if (output == null)
            {
                Files.createDirectories(writeDirectory);
                pruneOldFiles(writeDirectory);
                output = Files.newBufferedWriter(writeDirectory.resolve(writeFileName), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
            }
            output.write(line);
            output.flush();
        }
        catch (IOException ignored)
        {
            // Logging must never interfere with plugin or client operation.
        }
    }

    private void pruneOldFiles(Path targetDirectory)
    {
        // Retain at most 100 fixtures per raid mode to bound local disk usage.
        try (java.util.stream.Stream<Path> files = Files.list(targetDirectory))
        {
            java.util.List<Path> old = files
                .filter(path -> path.getFileName().toString().endsWith(".jsonl"))
                .sorted(Comparator.comparingLong(this::modifiedTime))
                .collect(java.util.stream.Collectors.toList());
            while (old.size() >= 100)
            {
                Files.deleteIfExists(old.remove(0));
            }
        }
        catch (IOException ignored)
        {
        }
    }

    private long modifiedTime(Path path)
    {
        try
        {
            return Files.getLastModifiedTime(path).toMillis();
        }
        catch (IOException ignored)
        {
            return Long.MIN_VALUE;
        }
    }

    private synchronized void closeOutput()
    {
        if (output != null)
        {
            try
            {
                output.close();
            }
            catch (IOException ignored)
            {
            }
            output = null;
        }
    }

    private static String quote(String value)
    {
        if (value == null)
        {
            return "null";
        }
        return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
    }

    private static String bounded(String value, int maxLength)
    {
        if (value == null)
        {
            return null;
        }
        return value.length() <= maxLength ? value : value.substring(0, maxLength);
    }

    private static String modeDirectory(String raidMode)
    {
        if ("cm".equalsIgnoreCase(raidMode) || "challenge".equalsIgnoreCase(raidMode))
        {
            return "cm";
        }
        if ("full".equalsIgnoreCase(raidMode))
        {
            return "full";
        }
        return "normal";
    }

    @Override
    public void close()
    {
        if (!enabled)
        {
            writer.shutdownNow();
            return;
        }
        endSession("plugin_shutdown");
        writer.shutdown();
        try
        {
            writer.awaitTermination(2, TimeUnit.SECONDS);
        }
        catch (InterruptedException ignored)
        {
            // RuneLite is already shutting down; queued fixture writes may be abandoned.
        }
    }

    static final class Metadata
    {
        // Construction bounds every caller-supplied value before persistence.
        final String raidMode;
        final String startReason;
        final String layoutCode;
        final int scale;
        final String scaleSource;
        final int thievingLevel;
        final String thievingSource;
        final int fishingLevel;
        final String fishingSource;

        Metadata(
            String raidMode,
            String startReason,
            String layoutCode,
            int scale,
            String scaleSource,
            int thievingLevel,
            String thievingSource,
            int fishingLevel,
            String fishingSource
        )
        {
            this.raidMode = bounded(raidMode, 12);
            this.startReason = bounded(startReason, 24);
            this.layoutCode = bounded(layoutCode, 64);
            this.scale = Math.max(1, Math.min(100, scale));
            this.scaleSource = bounded(scaleSource, 16);
            this.thievingLevel = Math.max(0, Math.min(5_000, thievingLevel));
            this.thievingSource = bounded(thievingSource, 24);
            this.fishingLevel = Math.max(1, Math.min(99, fishingLevel));
            this.fishingSource = bounded(fishingSource, 16);
        }
    }
}

package com.coxmegascale;

import com.coxmegascale.calc.RaidMath;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

/**
 * Writes one local, human-readable JSON summary after each completed raid.
 * Unlike anonymous point fixtures, summaries intentionally retain the display
 * names observed in the raid roster; they remain local and are documented as
 * private files in the README. All disk work runs on one daemon thread.
 */
final class RaidSummaryLogger implements AutoCloseable
{
    private static final DateTimeFormatter FILE_TIME = DateTimeFormatter
        .ofPattern("yyyy-MM-dd_HH-mm-ss", Locale.US)
        .withZone(ZoneOffset.UTC);

    private final Path directory;
    private final ExecutorService writer = Executors.newSingleThreadExecutor(r -> {
        Thread thread = new Thread(r, "cox-raid-summary-writer");
        thread.setDaemon(true);
        return thread;
    });

    RaidSummaryLogger(Path runeLiteDirectory)
    {
        directory = runeLiteDirectory.resolve("cox-assistant").resolve("raid-logs");
    }

    void write(Snapshot snapshot)
    {
        // Serialize before queueing so the immutable snapshot is never read by a
        // writer concurrently with plugin state changes.
        if (snapshot == null)
        {
            return;
        }
        String json = toJson(snapshot);
        String safeMode = fileComponent(snapshot.raidMode);
        String fileName = FILE_TIME.format(snapshot.completedAt) + "_" + safeMode + "_scale-"
            + Math.max(1, snapshot.scale) + "_" + UUID.randomUUID() + ".json";
        writer.execute(() -> writeFile(fileName, json));
    }

    private void writeFile(String fileName, String json)
    {
        try
        {
            Files.createDirectories(directory);
            Files.write(directory.resolve(fileName), json.getBytes(StandardCharsets.UTF_8));
        }
        catch (IOException ignored)
        {
            // Summary logging must never interfere with the client or gameplay.
        }
    }

    static String toJson(Snapshot snapshot)
    {
        // JSON is emitted explicitly to keep the plugin dependency-free and the
        // exact local data schema reviewable in this file.
        StringBuilder json = new StringBuilder(2_048);
        json.append("{\n");
        field(json, 1, "schemaVersion", 1, true);
        field(json, 1, "startedAt", snapshot.startedAt.toString(), true);
        field(json, 1, "completedAt", snapshot.completedAt.toString(), true);
        field(json, 1, "durationMillis", snapshot.durationMillis, true);
        field(json, 1, "raidMode", snapshot.raidMode, true);
        field(json, 1, "layout", snapshot.layout, true);
        field(json, 1, "scale", snapshot.scale, true);
        field(json, 1, "olmKillers", snapshot.olmKillers, true);

        indent(json, 1).append("\"participants\": [");
        for (int i = 0; i < snapshot.participants.size(); i++)
        {
            if (i > 0) json.append(", ");
            json.append(quote(snapshot.participants.get(i)));
        }
        json.append("],\n");

        indent(json, 1).append("\"points\": {\n");
        field(json, 2, "group", snapshot.groupPoints, true);
        field(json, 2, "personal", snapshot.personalPoints, true);
        field(json, 2, "personalSharePercent", percent(snapshot.personalPoints, snapshot.groupPoints), false);
        indent(json, 1).append("},\n");

        purple(json, "groupPurple", snapshot.groupPurple, true);
        purple(json, "personalPurple", snapshot.personalPurple, true);

        indent(json, 1).append("\"trackedTotals\": {\n");
        field(json, 2, "deathPointsLost", snapshot.deathPointsLost, true);
        field(json, 2, "overloadPoints", snapshot.overloadPoints, true);
        field(json, 2, "fishPoints", snapshot.fishPoints, false);
        indent(json, 1).append("},\n");

        indent(json, 1).append("\"scoutedRooms\": [");
        for (int i = 0; i < snapshot.scoutedRooms.size(); i++)
        {
            if (i > 0) json.append(", ");
            json.append(quote(snapshot.scoutedRooms.get(i)));
        }
        json.append("],\n");

        indent(json, 1).append("\"rooms\": [");
        if (!snapshot.rooms.isEmpty()) json.append('\n');
        for (int i = 0; i < snapshot.rooms.size(); i++)
        {
            Room room = snapshot.rooms.get(i);
            indent(json, 2).append("{\n");
            field(json, 3, "name", room.name, true);
            field(json, 3, "durationMillis", room.durationMillis, true);
            field(json, 3, "groupPoints", room.groupPoints, true);
            field(json, 3, "personalPoints", room.personalPoints, true);
            field(json, 3, "personalSharePercent", percent(room.personalPoints, room.groupPoints), false);
            indent(json, 2).append('}');
            json.append(i + 1 < snapshot.rooms.size() ? ",\n" : "\n");
        }
        if (!snapshot.rooms.isEmpty()) indent(json, 1);
        json.append("],\n");

        indent(json, 1).append("\"deaths\": [");
        if (!snapshot.deaths.isEmpty()) json.append('\n');
        for (int i = 0; i < snapshot.deaths.size(); i++)
        {
            Death death = snapshot.deaths.get(i);
            indent(json, 2).append("{\n");
            field(json, 3, "room", death.room, true);
            field(json, 3, "pointsLost", death.pointsLost, false);
            indent(json, 2).append('}');
            json.append(i + 1 < snapshot.deaths.size() ? ",\n" : "\n");
        }
        if (!snapshot.deaths.isEmpty()) indent(json, 1);
        json.append("]\n}\n");
        return json.toString();
    }

    private static void purple(StringBuilder json, String name, RaidMath.PurpleChance chance, boolean comma)
    {
        indent(json, 1).append(quote(name)).append(": {\n");
        field(json, 2, "points", chance.points, true);
        field(json, 2, "chanceAtLeastOnePercent", (1.0 - chance.distribution.get(0)) * 100.0, true);
        field(json, 2, "expectedPurples", chance.expectedPurples, true);
        field(json, 2, "potentialRolls", chance.potentialRolls, true);
        indent(json, 2).append("\"rollChancesPercent\": [");
        for (int i = 0; i < chance.rollProbabilities.size(); i++)
        {
            if (i > 0) json.append(", ");
            json.append(decimal(chance.rollProbabilities.get(i) * 100.0));
        }
        json.append("]\n");
        indent(json, 1).append('}').append(comma ? ",\n" : "\n");
    }

    private static void field(StringBuilder json, int level, String name, String value, boolean comma)
    {
        indent(json, level).append(quote(name)).append(": ").append(quote(value)).append(comma ? ",\n" : "\n");
    }

    private static void field(StringBuilder json, int level, String name, long value, boolean comma)
    {
        indent(json, level).append(quote(name)).append(": ").append(value).append(comma ? ",\n" : "\n");
    }

    private static void field(StringBuilder json, int level, String name, double value, boolean comma)
    {
        indent(json, level).append(quote(name)).append(": ").append(decimal(value)).append(comma ? ",\n" : "\n");
    }

    private static StringBuilder indent(StringBuilder json, int level)
    {
        for (int i = 0; i < level; i++) json.append("  ");
        return json;
    }

    private static double percent(int numerator, int denominator)
    {
        return denominator <= 0 ? 0 : Math.max(0, numerator) * 100.0 / denominator;
    }

    private static String decimal(double value)
    {
        return String.format(Locale.US, "%.6f", Math.max(0, value));
    }

    private static String quote(String value)
    {
        if (value == null) return "null";
        StringBuilder escaped = new StringBuilder(value.length() + 2).append('"');
        for (int i = 0; i < value.length(); i++)
        {
            char c = value.charAt(i);
            switch (c)
            {
                case '"': escaped.append("\\\""); break;
                case '\\': escaped.append("\\\\"); break;
                case '\b': escaped.append("\\b"); break;
                case '\f': escaped.append("\\f"); break;
                case '\n': escaped.append("\\n"); break;
                case '\r': escaped.append("\\r"); break;
                case '\t': escaped.append("\\t"); break;
                default:
                    if (c < 0x20) escaped.append(String.format(Locale.US, "\\u%04x", (int) c));
                    else escaped.append(c);
            }
        }
        return escaped.append('"').toString();
    }

    private static String fileComponent(String value)
    {
        String safe = value == null ? "unknown" : value.toLowerCase(Locale.US).replaceAll("[^a-z0-9_-]", "-");
        return safe.isEmpty() ? "unknown" : safe;
    }

    @Override
    public void close()
    {
        writer.shutdown();
        try
        {
            writer.awaitTermination(2, TimeUnit.SECONDS);
        }
        catch (InterruptedException ignored)
        {
            // RuneLite is already shutting down; queued summary writes may be abandoned.
        }
    }

    static final class Snapshot
    {
        final Instant startedAt;
        final Instant completedAt;
        final long durationMillis;
        final String raidMode;
        final String layout;
        final int scale;
        final int olmKillers;
        final List<String> participants;
        final int groupPoints;
        final int personalPoints;
        final RaidMath.PurpleChance groupPurple;
        final RaidMath.PurpleChance personalPurple;
        final int deathPointsLost;
        final int overloadPoints;
        final int fishPoints;
        final List<String> scoutedRooms;
        final List<Room> rooms;
        final List<Death> deaths;

        Snapshot(Instant startedAt, Instant completedAt, String raidMode, String layout, int scale, int olmKillers,
            List<String> participants, int groupPoints, int personalPoints, RaidMath.PurpleChance groupPurple,
            RaidMath.PurpleChance personalPurple, int deathPointsLost, int overloadPoints, int fishPoints,
            List<String> scoutedRooms, List<Room> rooms, List<Death> deaths)
        {
            this.completedAt = completedAt == null ? Instant.now() : completedAt;
            this.startedAt = startedAt == null ? this.completedAt : startedAt;
            this.durationMillis = Math.max(0, this.completedAt.toEpochMilli() - this.startedAt.toEpochMilli());
            this.raidMode = raidMode == null ? "unknown" : raidMode;
            this.layout = layout == null ? "Unknown" : layout;
            this.scale = Math.max(1, scale);
            this.olmKillers = Math.max(1, olmKillers);
            this.participants = immutable(participants);
            this.groupPoints = Math.max(0, groupPoints);
            this.personalPoints = Math.max(0, personalPoints);
            this.groupPurple = groupPurple;
            this.personalPurple = personalPurple;
            this.deathPointsLost = Math.max(0, deathPointsLost);
            this.overloadPoints = Math.max(0, overloadPoints);
            this.fishPoints = Math.max(0, fishPoints);
            this.scoutedRooms = immutable(scoutedRooms);
            this.rooms = immutable(rooms);
            this.deaths = immutable(deaths);
        }

        private static <T> List<T> immutable(List<T> values)
        {
            return values == null ? Collections.emptyList()
                : Collections.unmodifiableList(new ArrayList<>(values));
        }
    }

    static final class Room
    {
        final String name;
        final long durationMillis;
        final int groupPoints;
        final int personalPoints;

        Room(String name, long durationMillis, int groupPoints, int personalPoints)
        {
            this.name = name == null ? "Unknown" : name;
            this.durationMillis = Math.max(0, durationMillis);
            this.groupPoints = Math.max(0, groupPoints);
            this.personalPoints = Math.max(0, personalPoints);
        }
    }

    static final class Death
    {
        final String room;
        final int pointsLost;

        Death(String room, int pointsLost)
        {
            this.room = room == null ? "Unknown" : room;
            this.pointsLost = Math.max(0, pointsLost);
        }
    }
}

