        assertEquals(true, state.hasSharedStorageSnapshot());
        assertEquals(0, state.getSharedStorageCount("Noxifer"));
    }

    @Test
    public void recordsCraftedPotionOnlyAfterMakeAction()
    {
        CoxMegascaleState state = new CoxMegascaleState();
        ItemContainer inventory = mock(ItemContainer.class);

        when(inventory.getItems()).thenReturn(new Item[0]);
        assertEquals(false, state.observeInventory(inventory));
        when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.REVITALISATION_4, 1)});
        assertEquals(false, state.observeInventory(inventory));
        assertEquals(0, state.getCraftedPotions("Revitalisation"));

        state.notePotionCraftAction();
        when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.REVITALISATION_4, 1), new Item(ItemID.REVITALISATION_4, 1)});
        assertEquals(true, state.observeInventory(inventory));
        assertEquals(1, state.getCraftedPotions("Revitalisation"));
    }

    @Test
    public void keepsPrepCreditAfterIngredientsBecomeConfirmedPotions()
    {
        CoxMegascaleState state = new CoxMegascaleState();
        ItemContainer inventory = mock(ItemContainer.class);

        when(inventory.getItems()).thenReturn(new Item[]{
            new Item(ItemID.GOLPAR, 30), new Item(ItemID.STINKHORN_MUSHROOM, 30)
        });
        assertEquals(true, state.observeInventory(inventory));

        state.notePotionCraftAction();
        when(inventory.getItems()).thenReturn(new Item[]{
            new Item(ItemID.GOLPAR, 24), new Item(ItemID.STINKHORN_MUSHROOM, 24), new Item(ItemID.ELDER_4, 6)
        });
        assertEquals(true, state.observeInventory(inventory));

        assertEquals(6, state.getCraftedPotions("Elder"));
        assertEquals(30, state.getCollected(state.getResources().get(1)));
        assertEquals(30, state.getCollected(state.getResources().get(3)));
        assertEquals(30, state.getLocalPrepResources().stream().filter(count -> "Golpar".equals(count.name)).findFirst().get().count);
        assertEquals(30, state.getLocalPrepResources().stream().filter(count -> "Stinkhorn".equals(count.name)).findFirst().get().count);
    }

    @Test
    public void infersPotionCraftWhenCoxMakeWidgetOmitsMenuEvent()
    {
        CoxMegascaleState state = new CoxMegascaleState();
        ItemContainer inventory = mock(ItemContainer.class);

        when(inventory.getItems()).thenReturn(new Item[]{
            new Item(ItemID.GOLPAR, 10), new Item(ItemID.STINKHORN_MUSHROOM, 10)
        });
        assertEquals(true, state.observeInventory(inventory));

        // Mixing through the CoX widget may not produce MenuOptionClicked.
        // The ingredient reduction plus potion increase is sufficient to
        // identify the craft without counting a bank withdrawal/pickup.
        when(inventory.getItems()).thenReturn(new Item[]{
            new Item(ItemID.GOLPAR, 9), new Item(ItemID.STINKHORN_MUSHROOM, 9), new Item(ItemID.ELDER_4, 1)
        });
        assertEquals(true, state.observeInventory(inventory));
        assertEquals(1, state.getCraftedPotions("Elder"));
    }

    @Test
    public void doesNotCountPotionBankWithdrawalOrPickupAsCrafting()
    {
        CoxMegascaleState state = new CoxMegascaleState();
        ItemContainer inventory = mock(ItemContainer.class);

        when(inventory.getItems()).thenReturn(new Item[0]);
        state.observeInventory(inventory);
        when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.ELDER_4, 1)});
        state.observeInventory(inventory);

        assertEquals(0, state.getCraftedPotions("Elder"));
    }

    @Test
    public void raidResetPreservesFixtureOnlyWhileStillInsideCox()
    {
        assertEquals(true, CoxMegascalePlugin.shouldPreservePointFixtureOnRaidReset(true));
        assertEquals(false, CoxMegascalePlugin.shouldPreservePointFixtureOnRaidReset(false));
    }

    @Test
    public void completedFixtureCannotReopenBeforeRaidExit()
    {
        assertEquals(false, CoxMegascalePlugin.canOpenPointFixture(true, false, true,
            true, true, 100, "ABCDEF"));
        assertEquals(true, CoxMegascalePlugin.canOpenPointFixture(true, false, false,
            true, true, 100, "ABCDEF"));
    }

    @Test
    public void scoutingAloneCannotOpenFixture()
    {
        assertEquals(false, CoxMegascalePlugin.canOpenPointFixture(true, false, false,
            false, true, 100, "ABCDEF"));
        assertEquals(false, CoxMegascalePlugin.canOpenPointFixture(true, false, false,
            true, false, 100, "ABCDEF"));
    }

    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(CoxMegascalePlugin.class);
        RuneLite.main(args);
    }
}

package com.coxmegascale;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Verifies fixture anonymity, sequencing, retention, and session boundaries. */
public class PointFixtureLoggerTest
{
    @Test
    public void disabledDoesNotCreateFiles() throws Exception
    {
        Path root = Files.createTempDirectory("cox-fixtures");
        PointFixtureLogger logger = new PointFixtureLogger(false, root);
        logger.startRaid(metadata("normal", "raid_start"), 0, 0);
        logger.close();
        assertFalse(Files.exists(root.resolve("cox-assistant")));
    }

    @Test
    public void writesAnonymousVersionedPointTimeline() throws Exception
    {
        Path root = Files.createTempDirectory("cox-fixtures");
        PointFixtureLogger logger = new PointFixtureLogger(true, root);
        logger.startRaid(metadata("cm", "raid_start"), 100, 40);
        logger.room("room_entry", "Mystics", 120, 55, "room_entry_observed");
        logger.room("points_update", "Mystics", 105, 45, "local_death_observed");
        logger.raidComplete(200, 90);
        logger.close();

        String contents = readOnlyFixture(root);
        assertTrue(contents.contains("\"schemaVersion\":2"));
        assertTrue(contents.contains("\"startReason\":\"raid_start\""));
        assertTrue(contents.contains("\"layoutCode\":\"ABCDEF\""));
        assertTrue(contents.contains("\"scaleSource\":\"detected\""));
        assertTrue(contents.contains("\"thievingSource\":\"compatible_party_sum\""));
        assertTrue(contents.contains("\"fishingSource\":\"manual_override\""));
        assertTrue(contents.contains("\"groupDelta\":20"));
        assertTrue(contents.contains("\"personalDelta\":15"));
        assertTrue(contents.contains("\"pointSource\":\"local_death_observed\""));
        assertTrue(contents.contains("\"completed\":true"));
        assertTrue(contents.contains("\"endReason\":\"completed\""));
        assertTrue(contents.contains("\"sequence\":0"));
        assertTrue(contents.contains("\"sequence\":3"));
        assertFalse(contents.contains("ExamplePlayer"));
        assertFalse(contents.contains("username"));
        assertFalse(contents.contains("displayName"));
        assertFalse(contents.contains("memberId"));
        assertFalse(contents.contains("world"));
        assertFalse(contents.contains("timestamp"));
        assertFalse(contents.contains("sessionId"));
    }

    @Test
    public void repeatedStartAndRescoutStayInOneFile() throws Exception
    {
        Path root = Files.createTempDirectory("cox-fixtures");
        PointFixtureLogger logger = new PointFixtureLogger(true, root);
        logger.startRaid(metadata("normal", "raid_start"), 0, 0);
        logger.startRaid(metadata("normal", "raid_start"), 0, 0);
        logger.room("room_entry", "Tekton", 50, 45, "room_entry_observed");
        logger.room("room_exit", "Tekton", 75, 65, "room_exit_observed");
        logger.endSession("raid_exit");
        logger.close();

        List<Path> files = fixtureFiles(root);
        assertEquals(1, files.size());
        String contents = new String(Files.readAllBytes(files.get(0)), StandardCharsets.UTF_8);
        assertEquals(1, occurrences(contents, "\"event\":\"raid_start\""));
        assertTrue(contents.contains("\"completed\":false"));
        assertTrue(contents.contains("\"endReason\":\"raid_exit\""));
    }

    @Test
    public void doesNotCreateStartOnlyScoutFile() throws Exception
    {
        Path root = Files.createTempDirectory("cox-fixtures");
        PointFixtureLogger logger = new PointFixtureLogger(true, root);
        logger.startRaid(metadata("normal", "enabled_mid_raid"), 0, 0);
        logger.endSession("raid_exit");
        logger.close();
        assertTrue(fixtureFiles(root).isEmpty());
    }

    @Test
    public void completedRaidAndNextRaidUseSeparateFiles() throws Exception
    {
        Path root = Files.createTempDirectory("cox-fixtures");
        PointFixtureLogger logger = new PointFixtureLogger(true, root);
        logger.startRaid(metadata("full", "raid_start"), 0, 0);
        logger.room("room_entry", "Tekton", 50, 45, "room_entry_observed");
        logger.raidComplete(50, 45);
        logger.startRaid(metadata("cm", "raid_start"), 0, 0);
        logger.room("room_entry", "Tekton", 50, 45, "room_entry_observed");
        logger.close();

        assertEquals(2, fixtureFiles(root).size());
        assertTrue(Files.list(root.resolve("cox-assistant/point-fixtures/full")).findAny().isPresent());
        assertTrue(Files.list(root.resolve("cox-assistant/point-fixtures/cm")).findAny().isPresent());
    }

    private static PointFixtureLogger.Metadata metadata(String mode, String startReason)
    {
        return new PointFixtureLogger.Metadata(mode, startReason, "ABCDEF", 100, "detected",
            8_900, "compatible_party_sum", 99, "manual_override");
    }

    private static String readOnlyFixture(Path root) throws Exception
    {
        List<Path> files = fixtureFiles(root);
        assertEquals(1, files.size());
        return new String(Files.readAllBytes(files.get(0)), StandardCharsets.UTF_8);
    }

    private static List<Path> fixtureFiles(Path root) throws Exception
    {
        Path fixtureRoot = root.resolve("cox-assistant/point-fixtures");
        if (!Files.exists(fixtureRoot))
        {
            return java.util.Collections.emptyList();
        }
        try (java.util.stream.Stream<Path> paths = Files.walk(fixtureRoot))
        {
            return paths.filter(path -> path.getFileName().toString().endsWith(".jsonl"))
                .collect(Collectors.toList());
        }
    }

    private static int occurrences(String text, String needle)
    {
        int count = 0;
        for (int index = text.indexOf(needle); index >= 0; index = text.indexOf(needle, index + needle.length()))
        {
            count++;
        }
        return count;
    }
}

package com.coxmegascale;

import com.coxmegascale.calc.RaidMath;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Verifies the explicit local raid-summary schema and JSON escaping. */
public class RaidSummaryLoggerTest
{
    @Test
    public void writesOneReadableJsonFileForCompletedRaid() throws Exception
    {
        Path root = Files.createTempDirectory("cox-raid-summary");
        RaidMath math = new RaidMath();
        RaidSummaryLogger logger = new RaidSummaryLogger(root);
        RaidSummaryLogger.Snapshot snapshot = new RaidSummaryLogger.Snapshot(
            Instant.parse("2026-07-21T20:00:00Z"),
            Instant.parse("2026-07-21T20:30:00Z"),
            "full",
            "ABC123",
            100,
            10,
            Arrays.asList("Raider One", "Raider \"Two\""),
            867_500,
            86_750,
            math.calculatePurpleChance(867_500),
            math.calculatePurpleChance(86_750),
            1_000,
            4_000,
            3_000,
            Arrays.asList("Mystics", "Olm"),
            Arrays.asList(
                new RaidSummaryLogger.Room("Mystics", 60_000, 10_000, 2_500),
                new RaidSummaryLogger.Room("Olm", 300_000, 100_000, 10_000)),
            Collections.singletonList(new RaidSummaryLogger.Death("Olm", 1_000)));

        logger.write(snapshot);
        logger.close();

        Path directory = root.resolve("cox-assistant").resolve("raid-logs");
        List<Path> files = Files.list(directory).collect(Collectors.toList());
        assertEquals(1, files.size());
        assertTrue(files.get(0).getFileName().toString().endsWith(".json"));
        String json = new String(Files.readAllBytes(files.get(0)), StandardCharsets.UTF_8);
        assertTrue(json.contains("\"durationMillis\": 1800000"));
        assertTrue(json.contains("\"participants\": [\"Raider One\", \"Raider \\\"Two\\\"\"]"));
        assertTrue(json.contains("\"personalSharePercent\": 25.000000"));
        assertTrue(json.contains("\"chanceAtLeastOnePercent\": 77.466801"));
        assertTrue(json.contains("\"name\": \"Olm\""));
        assertTrue(json.contains("\"pointsLost\": 1000"));
    }
}

package com.coxmegascale.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

import java.util.Collections;
import org.junit.Test;

/** Regression examples for scaling anchors, point estimates, caps, and odds. */
public class RaidMathTest
{
    private final RaidMath raidMath = new RaidMath();

    @Test
    public void purpleChanceMatchesKnownExample()
    {
        RaidMath.PurpleChance result = raidMath.calculatePurpleChance(957_000);

        assertEquals(2, result.potentialRolls);
        assertEquals("19.00%", RaidMath.formatPercent(result.distribution.get(0)));
        assertEquals("51.69%", RaidMath.formatPercent(result.distribution.get(1)));
        assertEquals("29.31%", RaidMath.formatPercent(result.distribution.get(2)));
    }

    @Test
    public void roomPointsMatchKnownScale()
    {
        RaidMath.RoomPoints result = raidMath.calculateRoomPoints(22, RaidMath.RaidOptions.defaults(22));

        assertEquals(534_729, result.grandTotal);
    }

    @Test
    public void crabsAddFixedExpectedPointsWhenPresentInLayout()
    {
        RaidMath.RaidOptions options = new RaidMath.RaidOptions(
            22,
            0,
            75,
            RaidMath.PUZZLE_ICE_DEMON,
            RaidMath.PUZZLE_TIGHTROPE,
            false,
            true
        );
        RaidMath.RoomPoints result = raidMath.calculateRoomPoints(22, options);

        assertEquals(536_329, result.grandTotal);
        assertEquals("Crabs", result.rooms.get(3).name);
        assertEquals(1_600, result.rooms.get(3).points);
    }

    @Test
    public void zeroPointsHaveZeroPurpleChance()
    {
        RaidMath.PurpleChance result = raidMath.calculatePurpleChance(0);
        assertEquals(0, result.points);
        assertEquals(0, result.potentialRolls);
        assertEquals(0.0, result.expectedPurples, 0.0);
        assertEquals(1.0, result.distribution.get(0), 0.0);
    }

    @Test
    public void purpleRollsUseExactBoundariesAndCapAtSix()
    {
        assertEquals(1, raidMath.calculatePurpleChance(570_000).potentialRolls);
        assertEquals(2, raidMath.calculatePurpleChance(570_001).potentialRolls);
        RaidMath.PurpleChance capped = raidMath.calculatePurpleChance(4_000_000);
        assertEquals(6, capped.potentialRolls);
        assertEquals(3_420_000 / 867_500.0, capped.expectedPurples, 0.000_000_1);
    }

    @Test
    public void fishingCapUsesRaidScaleWithoutPotionBonusDoses()
    {
        assertEquals(20, raidMath.calculateFishingPoints(1, 75).fishToCap);
        assertEquals(440, raidMath.calculateFishingPoints(22, 75).fishToCap);
        assertEquals(2_000, raidMath.calculateFishingPoints(100, 75).fishToCap);
    }

    @Test
    public void scoutedRoomOptionsExcludeAbsentCombatRoomsAndCountDuplicatePuzzles()
    {
        RaidMath.RaidOptions options = new RaidMath.RaidOptions(22, 0, 75,
            RaidMath.PUZZLE_TIGHTROPE, RaidMath.PUZZLE_TIGHTROPE, "", false, false, 12,
            false, true, false, false);

        RaidMath.RoomPoints result = raidMath.calculateRoomPoints(22, options);
        assertEquals(0, result.rooms.stream().filter(row -> "guardians".equals(row.key)).count());
        assertEquals(1, result.rooms.stream().filter(row -> "mystics".equals(row.key)).count());
        assertEquals(2, result.rooms.stream().filter(row -> "tightrope".equals(row.key)).count());
    }

    @Test
    public void missingCombatRoomsUseBaselineContributionEstimates()
    {
        RaidMath.RaidOptions options = new RaidMath.RaidOptions(100, 0, 75,
            "", "", "", false, false, 0,
            false, false, false, true, true, true, true, true, false);

        RaidMath.RoomPoints result = raidMath.calculateRoomPoints(100, options);

        assertEquals(5, result.rooms.stream()
            .filter(row -> row.note != null && row.note.contains("Combat contribution estimate"))
            .count());
        assertEquals(2_271, raidMath.calculateMuttadilesPoints(1));
        assertEquals(1_362, raidMath.calculateTektonPoints(1));
        assertEquals(2_282, raidMath.calculateVasaPoints(1));
        assertEquals(1_948, raidMath.calculateVespulaPoints(1));
        assertEquals(2_497, raidMath.calculateVanguardsPoints(1));
        assertEquals(4_205, raidMath.calculateMuttadilesPoints(2));
        assertEquals(2_467, raidMath.calculateTektonPoints(2));
        assertEquals(3_498, raidMath.calculateVasaPoints(2));
        assertEquals(3_383, raidMath.calculateVespulaPoints(2));
        assertEquals(5_410, raidMath.calculateVanguardsPoints(2));
    }

    @Test
    public void overloadSipOverrideChangesExpectedOverloadPoints()
    {
        RaidMath.RaidOptions options = new RaidMath.RaidOptions(
            22,
            0,
            75,
            RaidMath.PUZZLE_ICE_DEMON,
            RaidMath.PUZZLE_TIGHTROPE,
            false,
            false,
            12
        );

        RaidMath.RoomPoints result = raidMath.calculateRoomPoints(22, options);
        RaidMath.PointRow overloads = result.rooms.stream()
            .filter(row -> "overloads".equals(row.key))
            .findFirst()
            .orElseThrow(AssertionError::new);

        assertEquals(7_200, overloads.points);
        assertEquals(472_929, result.grandTotal);
    }

    @Test
    public void calculatesOnlyTheRemainingOverloadPointsForCurrentExpected()
    {
        assertEquals(300_000, raidMath.calculateRemainingOverloadPoints(5, 505));
        assertEquals(0, raidMath.calculateRemainingOverloadPoints(505, 505));
        assertEquals(0, raidMath.calculateRemainingOverloadPoints(506, 505));
    }

    @Test
    public void iceDemonStatsStayFixedAcrossRaidScale()
    {
        RaidMath.StatSection puzzleRooms = raidMath.calculateNpcStats(100).stream()
            .filter(section -> "puzzleRooms".equals(section.key))
            .findFirst()
            .orElseThrow(AssertionError::new);
        RaidMath.StatGroup iceDemon = puzzleRooms.groups.stream()
            .filter(group -> "Ice Demon".equals(group.name))
            .findFirst()
            .orElseThrow(AssertionError::new);

        assertEquals(160, iceDemon.stats.get("defence").intValue());
        assertEquals(390, iceDemon.stats.get("magic").intValue());
    }

    @Test
    public void npcStatsAreReusedUntilTheScaleChanges()
    {
        java.util.List<RaidMath.StatSection> scaleHundred = raidMath.calculateNpcStats(100);
        assertSame(scaleHundred, raidMath.calculateNpcStats(100));
        java.util.List<RaidMath.StatSection> scaleNinetyNine = raidMath.calculateNpcStats(99);
        assertNotSame(scaleHundred, scaleNinetyNine);
        assertSame(scaleNinetyNine, raidMath.calculateNpcStats(99));
    }

    @Test
    public void olmPointsCapAtScaleFiftyOne()
    {
        RaidMath.OlmPoints result = raidMath.calculateOlmPoints(100);

        assertEquals(56_440, result.head);
        assertEquals(761_940, result.hands);
        assertEquals(818_380, result.total);
        assertEquals(9, result.phases);
        assertEquals(51, result.cappedScale);
    }

    @Test
    public void expectedOlmPointsShowHandsAndPerPhaseWithoutHead()
    {
        RaidMath.RoomPoints result = raidMath.calculateRoomPoints(100, RaidMath.RaidOptions.defaults(100));

        assertEquals("Olm hands", result.totals.get(0).name);
        assertEquals(761_940, result.totals.get(0).points);
        assertEquals("Per Phase", result.totals.get(1).name);
        assertEquals(84_660, result.totals.get(1).points);
    }

    @Test
    public void ralosCountsIndividualSuccessfulHits()
    {
        SpecPlanner planner = new SpecPlanner(raidMath);
        SpecPlanner.SpecSummary olmHead = planner.buildCoxSpecPlan(100, Collections.emptyList())
            .stream()
            .filter(summary -> "olmHead".equals(summary.roomKey))
            .findFirst()
            .orElseThrow(AssertionError::new);

        assertEquals(Integer.valueOf(5), olmHead.specs.get("Ralos"));
        assertEquals("5x Ralos", olmHead.lines.get(1));
    }

    @Test
    public void mysticsDefencePlanUsesElderMaulsThenRalos()
    {
        SpecPlanner planner = new SpecPlanner(raidMath);
        SpecPlanner.SpecSummary mystics = planner.buildCoxSpecPlan(100, Collections.emptyList())
            .stream()
            .filter(summary -> "mystics".equals(summary.roomKey))
            .findFirst()
            .orElseThrow(AssertionError::new);

        assertEquals(Integer.valueOf(2), mystics.specs.get("Elder Maul"));
        assertEquals(Integer.valueOf(4), mystics.specs.get("Ralos"));
        assertEquals(Integer.valueOf(2), mystics.allStatSpecs.get("Elder Maul"));
        assertEquals(Integer.valueOf(2), mystics.allStatSpecs.get("Ralos"));
    }
}
